// Detect whether the image pipeline actually produced a binary file.
const item = $input.first();
const hasImage = !!(item.binary && item.binary.data1);
return [{ json: { hasImage }, binary: item.binary }];

let rawJsonString = $input.first().json.text;
rawJsonString = rawJsonString.replace(/```json/gi, '').replace(/```/g, '').trim();
const parsedData = JSON.parse(rawJsonString);
parsedData.entry_id = $('Webhook').item.json.body.entry_id;
return [{ json: parsedData }];

const body = $input.first().json.body;

return [{
  json: {
    entry_id: body.entry_id,
    message: body.message,
    user_id: body.user_id,
    summary: body.catalog_context?.summary || '',
    tech_stack: JSON.stringify(body.catalog_context?.tech_stack || []),
    pros_cons: JSON.stringify(body.catalog_context?.pros_cons || {}),
    similar_tools: JSON.stringify(body.catalog_context?.similar_tools || []),
    raw_input: body.catalog_context?.raw_input || ''
  }
}];

const llmText = ($input.first().json.text || 'Sorry, I could not generate a response.').trim();
const entryId = $('Chat Extract Fields1').item.json.entry_id;

// Try to parse as JSON (MODE 2 — catalog edit)
let message = llmText;
let proposed_changes = null;

try {
  // Strip markdown code fences if the LLM wrapped it
  let cleanText = llmText;
  if (cleanText.startsWith('```')) {
    cleanText = cleanText.replace(/^```(?:json)?\n?/, '').replace(/\n?```$/, '').trim();
  }

  const parsed = JSON.parse(cleanText);

  if (parsed.message && parsed.proposed_changes) {
    message = parsed.message;
    proposed_changes = parsed.proposed_changes;
  }
} catch (e) {
  // Not JSON — it's a normal chat response (MODE 1)
  // Keep message as-is
}

const result = {
  entry_id: entryId,
  message: message
};

if (proposed_changes) {
  result.proposed_changes = proposed_changes;
}

return [{ json: result }];
